package com.commutemate.ride;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="ride_offers") public class RideOffer { @Id @GeneratedValue private UUID id; @Column(name="tenant_id",nullable=false) private UUID tenantId; @Column(name="driver_user_id",nullable=false) private UUID driverUserId; @Column(name="location_id",nullable=false) private UUID locationId; @Column(name="departure_at",nullable=false) private Instant departureAt; @Column(name="origin_geohash",nullable=false) private String originGeohash; @Column(name="seats_available",nullable=false) private short seatsAvailable; @Column(name="commute_intent",nullable=false) private String commuteIntent; @Column(nullable=false) private String status="OPEN"; protected RideOffer(){} public RideOffer(UUID tenantId,UUID driverUserId,UUID locationId,Instant departureAt,String originGeohash,short seatsAvailable,String commuteIntent){this.tenantId=tenantId;this.driverUserId=driverUserId;this.locationId=locationId;this.departureAt=departureAt;this.originGeohash=originGeohash;this.seatsAvailable=seatsAvailable;this.commuteIntent=commuteIntent;} public UUID getId(){return id;} public UUID getTenantId(){return tenantId;} public UUID getDriverUserId(){return driverUserId;} public UUID getLocationId(){return locationId;} public Instant getDepartureAt(){return departureAt;} public String getOriginGeohash(){return originGeohash;} public short getSeatsAvailable(){return seatsAvailable;} public String getCommuteIntent(){return commuteIntent;} public String getStatus(){return status;} public void reserveSeat(){if(!status.equals("OPEN")||seatsAvailable<1)throw new IllegalArgumentException("ride offer has no available seats");seatsAvailable--;if(seatsAvailable==0)status="FULL";} }
